ec) cout << \" \" << x;\n        cout << \"\\n\";\n    }\n\n    return 0;\n}\n\nEOF\n\ng++ -std=c++17 -O2 -pipe -o main main.cpp\n./main << 'EOF'\n6 7\n1 4\n5 2\n3 0\n5 5\n4 1\n0 3\n4 2\nEOF"], "duration": 0.9}
