, l, mid, pos, val);\n        else segUpd(idx<<1|1, mid+1, r, pos, val);\n        seg[idx] = seg[idx<<1] + seg[idx<<1|1];\n    };\n    function<int(int,int,int,int,int)> segFind = [&](int idx, int l, int r, int ql, int qr)->int{\n        if(qr < l || r < ql || seg[idx] == 0) return -1;\n        if(l == r) return l;\n        int mid = (l+r)>>1;\n        int leftRes = segFind(idx<<1, l, mid, ql, qr);\n        if(leftRes != -1) return leftRes;\n        return segFind(idx<<1|1, mid+1, r, ql, qr);\n    };\n\n    auto toggleNode = [&](int node){\n        int val = a[node];\n        if(!active[node]){\n            active[node] = 1;\n            cnt[val]++;\n            int parity = cnt[val] & 1;\n            segUpd(1, 1, n, val, parity);\n        } else {\n            active[node] = 0;\n            cnt[val]--;\n            int parity = cnt[val] & 1;\n            segUpd(1, 1, n, val, parity);\n        }\n    };\n\n    // Mo's sweep\n    int curL = 1, curR = 0;\n    vector<int> answer(q, -1);\n\n    for(const auto& qu : queries){\n        int L = qu.l, R = qu.r; // Euler interval\n        while(curL > L) toggleNode(E[--curL]);\n        while(curR < R) toggleNode(E[++curR]);\n        while(curL < L) toggleNode(E[curL++]);\n        while(curR > R) toggleNode(E[curR--]);\n\n        bool added = false;\n        int w = qu.lca;\n        if(qu.needLCA){\n            toggleNode(w);\n            added = true;\n        }\n        int ans = segFind(1, 1, n, qu.valL, qu.valR);\n        if(added) toggleNode(w);\n        answer[qu.idx] = (ans == -1 ? -1 : ans);\n    }\n\n    // Output\n    for(int i=0;i<q;i++){\n        cout << answer[i] << \"\\n\";\n    }\n\n    return 0;\n}\nCPP\n",
